-- UTF-8. V309 after V308: preserve entry identity; correct only 17 reviewed tenant-1 Leads.
-- Source and business submitter become media/provider; original operator/audit and owner stay intact.
-- source_dept_id uses the existing contribution department snapshot, never current organization.
-- Only historical source classification is corrected (including frozen facts by explicit user decision).
-- Organization, people credited, timestamps, amounts, repurchase classification and workflow facts stay intact.
-- Orders retain their actual submitter; only approval leadProfile source keys are corrected.
-- Before/after images in zsjos_data_repair_backup are captured once; later conflicting edits fail closed.
-- DDL commits implicitly: a failed run may leave the nullable column. Re-execution checks actual state.
-- Empty fresh DB: additive schema only, no business seeds. Partial manifest rejects.
-- Restore requires matching after-images, reviewed before-image recovery and later-migration review.
-- Do not replay older V298/V301 repair scripts after this migration. No role/menu changes or notifications.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
DROP PROCEDURE IF EXISTS zsjos_v309_apply;
DELIMITER $$
CREATE PROCEDURE zsjos_v309_apply()
BEGIN
 DECLARE v_count INT;
 DECLARE v_now DATETIME DEFAULT NOW();
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 IF NOT EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V308') OR NOT EXISTS(SELECT 1 FROM zsjos_module_schema_version WHERE module_code='core' AND version='V308') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 requires V308 in both ledgers';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_data_repair_backup' AND column_name='old_value' AND data_type='longtext') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 requires LONGTEXT repair backup';
 END IF;
 IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('zsjos_lead','zsjos_order_approval_round','zsjos_performance_attribution','zsjos_data_repair_backup','zsjos_schema_version','zsjos_module_schema_version') AND engine='InnoDB')<>6 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 requires transactional repair tables';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_lead' AND column_name='submission_source_type') THEN
  ALTER TABLE zsjos_lead ADD COLUMN submission_source_type VARCHAR(32) NULL COMMENT '录单入口身份来源，与业务引流来源分离' AFTER source_type;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_lead' AND column_name='submission_source_type' AND data_type='varchar' AND character_maximum_length=32 AND is_nullable='YES') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 incompatible entry identity column';
 END IF;
 DROP TEMPORARY TABLE IF EXISTS v309_manifest;
 CREATE TEMPORARY TABLE v309_manifest(lead_no VARCHAR(64) PRIMARY KEY,provider_id BIGINT NOT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

 SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
 START TRANSACTION;
 SELECT COUNT(*) INTO v_count FROM zsjos_lead l JOIN v309_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1 FOR UPDATE;
 IF v_count NOT IN (0,17) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 partial manifest'; END IF;
 IF EXISTS(SELECT 1 FROM zsjos_lead l JOIN v309_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1 AND
  (l.deleted<>0 OR l.source_type NOT IN ('sales_self_sourced','internal_new_media') OR l.source_provider_recorded<>1
   OR NOT(l.source_provider_user_id <=> m.provider_id) OR NOT(l.provider_owner_type <=> 'system_user')
   OR NOT(l.provider_owner_id <=> m.provider_id) OR NOT(l.contribution_user_id_snapshot <=> m.provider_id)
   OR l.contribution_dept_id_snapshot IS NULL OR l.provider_owner_name_snapshot IS NULL OR l.partner_id IS NOT NULL)) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 reviewed provider evidence changed';
 END IF;
 DROP TEMPORARY TABLE IF EXISTS v309_images;
 CREATE TEMPORARY TABLE v309_images(table_name VARCHAR(64),row_id BIGINT,current_image JSON,before_image JSON,after_image JSON,PRIMARY KEY(table_name,row_id));

 IF EXISTS(SELECT 1 FROM zsjos_data_repair_backup WHERE repair_key='media-assisted-source-v309' GROUP BY table_name,row_id,column_name HAVING COUNT(*)<>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 duplicate evidence'; END IF;
 IF EXISTS(SELECT 1 FROM zsjos_data_repair_backup b LEFT JOIN v309_images i ON i.table_name=b.table_name AND i.row_id=b.row_id WHERE b.repair_key='media-assisted-source-v309' AND (i.row_id IS NULL OR b.column_name NOT IN ('__before__','__after__'))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 evidence target missing'; END IF;
 IF EXISTS(SELECT 1 FROM v309_images i WHERE (SELECT COUNT(*) FROM zsjos_data_repair_backup b WHERE b.repair_key='media-assisted-source-v309' AND b.table_name=i.table_name AND b.row_id=i.row_id) NOT IN (0,2)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 incomplete images'; END IF;
 IF v_count=17 AND (EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V309') OR EXISTS(SELECT 1 FROM zsjos_module_schema_version WHERE module_code='core' AND version='V309')) AND (SELECT COUNT(*) FROM zsjos_data_repair_backup WHERE repair_key='media-assisted-source-v309')<>(SELECT COUNT(*)*2 FROM v309_images) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 ledger lacks evidence'; END IF;
 UPDATE v309_images i JOIN zsjos_data_repair_backup b ON b.repair_key='media-assisted-source-v309' AND b.table_name=i.table_name AND b.row_id=i.row_id AND b.column_name='__before__' JOIN zsjos_data_repair_backup a ON a.repair_key=b.repair_key AND a.table_name=b.table_name AND a.row_id=b.row_id AND a.column_name='__after__' SET i.before_image=CAST(b.old_value AS JSON),i.after_image=CAST(a.old_value AS JSON);
 IF EXISTS(SELECT 1 FROM v309_images WHERE current_image<>before_image AND current_image<>after_image) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 later edit conflicts with repair'; END IF;
 IF EXISTS(SELECT 1 FROM v309_images i WHERE i.table_name='zsjos_lead' AND i.before_image->>'$.source_type'<>'sales_self_sourced') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 original source evidence missing'; END IF;
 UPDATE zsjos_lead l JOIN v309_images i ON i.table_name='zsjos_lead' AND i.row_id=l.id SET l.source_type=NULLIF(i.after_image->>'$.source_type','null'),l.submission_source_type=NULLIF(i.after_image->>'$.submission_source_type','null'),l.source_user_id=NULLIF(i.after_image->>'$.source_user_id','null'),l.source_dept_id=NULLIF(i.after_image->>'$.source_dept_id','null'),l.version=NULLIF(i.after_image->>'$.version','null'),l.updater=NULLIF(i.after_image->>'$.updater','null'),l.update_time=NULLIF(i.after_image->>'$.update_time','null') WHERE l.tenant_id=1 AND i.current_image<>i.after_image;
 IF EXISTS(SELECT 1 FROM zsjos_lead l JOIN v309_images i ON i.table_name='zsjos_lead' AND i.row_id=l.id WHERE NOT(JSON_OBJECT('source_type',l.source_type,'submission_source_type',l.submission_source_type,'source_user_id',l.source_user_id,'source_dept_id',l.source_dept_id,'version',l.version,'updater',l.updater,'update_time',DATE_FORMAT(l.update_time,'%Y-%m-%d %H:%i:%s')) <=> i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 zsjos_lead postcondition failed'; END IF;
 UPDATE zsjos_order_approval_round r JOIN v309_images i ON i.table_name='zsjos_order_approval_round' AND i.row_id=r.id SET r.order_snapshot=i.after_image->'$.order_snapshot',r.version=NULLIF(i.after_image->>'$.version','null'),r.updater=NULLIF(i.after_image->>'$.updater','null'),r.update_time=NULLIF(i.after_image->>'$.update_time','null') WHERE r.tenant_id=1 AND i.current_image<>i.after_image;
 IF EXISTS(SELECT 1 FROM zsjos_order_approval_round r JOIN v309_images i ON i.table_name='zsjos_order_approval_round' AND i.row_id=r.id WHERE NOT(JSON_OBJECT('order_snapshot',r.order_snapshot,'version',r.version,'updater',r.updater,'update_time',DATE_FORMAT(r.update_time,'%Y-%m-%d %H:%i:%s')) <=> i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 zsjos_order_approval_round postcondition failed'; END IF;
 UPDATE zsjos_performance_attribution p JOIN v309_images i ON i.table_name='zsjos_performance_attribution' AND i.row_id=p.id SET p.source_group=NULLIF(i.after_image->>'$.source_group','null'),p.updater=NULLIF(i.after_image->>'$.updater','null'),p.update_time=NULLIF(i.after_image->>'$.update_time','null') WHERE p.tenant_id=1 AND i.current_image<>i.after_image;
 IF EXISTS(SELECT 1 FROM zsjos_performance_attribution p JOIN v309_images i ON i.table_name='zsjos_performance_attribution' AND i.row_id=p.id WHERE NOT(JSON_OBJECT('source_group',p.source_group,'updater',p.updater,'update_time',DATE_FORMAT(p.update_time,'%Y-%m-%d %H:%i:%s')) <=> i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 zsjos_performance_attribution postcondition failed'; END IF;

 -- V309 revision 2: 83 individually confirmed Leads; no current-role/name inference.
 -- Separate evidence key preserves original V309 before/after records. Runs inside the same transaction.
 DROP TEMPORARY TABLE IF EXISTS v309_r2_manifest;
 CREATE TEMPORARY TABLE v309_r2_manifest(lead_no VARCHAR(64) PRIMARY KEY,provider_id BIGINT NULL,entry_type VARCHAR(40)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

 SELECT COUNT(*) INTO v_count FROM zsjos_lead l JOIN v309_r2_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1 FOR UPDATE;
 IF v_count NOT IN (0,83) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 partial confirmed manifest'; END IF;
 IF v_count=83 AND (NOT EXISTS(SELECT 1 FROM system_users WHERE tenant_id=1 AND id=19 AND BINARY username='MoCaiQiao') OR NOT EXISTS(SELECT 1 FROM system_users WHERE tenant_id=1 AND id=527 AND BINARY username='LiangYing')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 confirmed employee identity missing'; END IF;
 IF v_count=0 AND EXISTS(SELECT 1 FROM zsjos_lead WHERE tenant_id=1 AND deleted=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 requires reviewed local dataset or empty fresh database'; END IF;
 DROP TEMPORARY TABLE IF EXISTS v309_r2_expected;
 CREATE TEMPORARY TABLE v309_r2_expected(table_name VARCHAR(64),row_id BIGINT,before_sha CHAR(64),PRIMARY KEY(table_name,row_id));
 DROP TEMPORARY TABLE IF EXISTS v309_r2_images;
 CREATE TEMPORARY TABLE v309_r2_images(table_name VARCHAR(64),row_id BIGINT,current_image JSON,before_image JSON,after_image JSON,PRIMARY KEY(table_name,row_id));
 JSON_SET(JSON_OBJECT('tenant_id',r.tenant_id,'deleted',CAST(r.deleted AS UNSIGNED),'order_id',r.order_id,'order_snapshot',CAST(r.order_snapshot AS JSON),'version',r.version,'updater',r.updater,'update_time',DATE_FORMAT(r.update_time,'%Y-%m-%d %H:%i:%s')),'$.order_snapshot',JSON_SET(CAST(r.order_snapshot AS JSON),
 '$.leadProfile.sourceType',IF(m.provider_id IS NULL,m.entry_type,'internal_new_media'),
 '$.leadProfile.sourceLabel',IF(m.provider_id IS NOT NULL,'新媒体提交',IF(m.entry_type='sales_self_sourced','销售自拓录','教务自拓录')),
 '$.leadProfile.sourceSubjectType','ADMIN','$.leadProfile.sourceSubjectId',IF(m.provider_id IS NULL,l.source_user_id,m.provider_id),
 '$.leadProfile.sourceUserName',IF(m.provider_id IS NULL,NULL,l.provider_owner_name_snapshot)),
 '$.version',r.version+1,'$.updater','V309-r2','$.update_time',DATE_FORMAT(v_now,'%Y-%m-%d %H:%i:%s'))
 FROM zsjos_order_approval_round r JOIN zsjos_order o ON o.id=r.order_id AND o.tenant_id=r.tenant_id
 JOIN zsjos_lead l ON l.id=o.lead_id AND l.tenant_id=o.tenant_id JOIN v309_r2_manifest m ON m.lead_no=l.lead_no
 WHERE l.tenant_id=1 AND o.deleted=0 AND r.deleted=0 AND JSON_TYPE(JSON_EXTRACT(r.order_snapshot,'$.leadProfile'))='OBJECT';
 IF(p.source_group=IF(m.provider_id IS NULL,'self','inbound'),JSON_OBJECT('tenant_id',p.tenant_id,'deleted',CAST(p.deleted AS UNSIGNED),'lead_id',p.lead_id,'fact_type',p.fact_type,'fact_id',p.fact_id,'source_group',p.source_group,'user_id',p.user_id,'dept_id',p.dept_id,'center_id',p.center_id,'org_source',p.org_source,'updater',p.updater,'update_time',DATE_FORMAT(p.update_time,'%Y-%m-%d %H:%i:%s')),JSON_SET(JSON_OBJECT('tenant_id',p.tenant_id,'deleted',CAST(p.deleted AS UNSIGNED),'lead_id',p.lead_id,'fact_type',p.fact_type,'fact_id',p.fact_id,'source_group',p.source_group,'user_id',p.user_id,'dept_id',p.dept_id,'center_id',p.center_id,'org_source',p.org_source,'updater',p.updater,'update_time',DATE_FORMAT(p.update_time,'%Y-%m-%d %H:%i:%s')),'$.source_group',IF(m.provider_id IS NULL,'self','inbound'),'$.updater','V309-r2','$.update_time',DATE_FORMAT(v_now,'%Y-%m-%d %H:%i:%s')))
 FROM zsjos_performance_attribution p JOIN zsjos_lead l ON l.id=p.lead_id AND l.tenant_id=p.tenant_id
 JOIN v309_r2_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1 AND p.deleted=0
 AND NOT(p.fact_type='ORDER' AND EXISTS(SELECT 1 FROM zsjos_order o WHERE o.id=p.fact_id AND o.tenant_id=p.tenant_id AND o.order_type='repurchase'));

 IF v_count=83 AND (SELECT COUNT(*) FROM v309_r2_images)<>333 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 related records changed'; END IF;
 IF EXISTS(SELECT 1 FROM v309_r2_images i LEFT JOIN v309_r2_expected e ON e.table_name=i.table_name AND e.row_id=i.row_id WHERE e.row_id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 unreviewed target'; END IF;
 IF EXISTS(SELECT 1 FROM zsjos_data_repair_backup WHERE repair_key='lead-source-confirmed-v309-r2' GROUP BY table_name,row_id,column_name HAVING COUNT(*)<>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 duplicate evidence'; END IF;
 IF EXISTS(SELECT 1 FROM zsjos_data_repair_backup b LEFT JOIN v309_r2_images i ON i.table_name=b.table_name AND i.row_id=b.row_id WHERE b.repair_key='lead-source-confirmed-v309-r2' AND (i.row_id IS NULL OR b.column_name NOT IN ('__before__','__after__','__provenance__'))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 evidence target missing'; END IF;
 IF EXISTS(SELECT 1 FROM v309_r2_images i WHERE (SELECT COUNT(*) FROM zsjos_data_repair_backup b WHERE b.repair_key='lead-source-confirmed-v309-r2' AND b.table_name=i.table_name AND b.row_id=i.row_id) NOT IN (0,3)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 incomplete evidence'; END IF;
 IF v_count=83 AND EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V309' AND (BINARY checksum=BINARY SHA2('lead-source-confirmed-v309-r2',256) OR BINARY checksum=BINARY @zsjos_v309_file_checksum)) AND (SELECT COUNT(*) FROM zsjos_data_repair_backup WHERE repair_key='lead-source-confirmed-v309-r2')<>(SELECT COUNT(*)*3 FROM v309_r2_images) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 success lacks evidence'; END IF;
 UPDATE v309_r2_images i JOIN zsjos_data_repair_backup b ON b.repair_key='lead-source-confirmed-v309-r2' AND b.table_name=i.table_name AND b.row_id=i.row_id AND b.column_name='__before__'
 JOIN zsjos_data_repair_backup a ON a.repair_key=b.repair_key AND a.table_name=b.table_name AND a.row_id=b.row_id AND a.column_name='__after__'
 SET i.before_image=CAST(b.old_value AS JSON),i.after_image=CAST(a.old_value AS JSON);
 IF EXISTS(SELECT 1 FROM v309_r2_images i JOIN v309_r2_expected e ON e.table_name=i.table_name AND e.row_id=i.row_id WHERE SHA2(CAST(i.before_image AS CHAR CHARACTER SET utf8mb4),256)<>e.before_sha) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 reviewed before image changed'; END IF;
 IF EXISTS(SELECT 1 FROM v309_r2_images WHERE current_image<>before_image AND current_image<>after_image) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 later edit conflicts'; END IF;
 UPDATE zsjos_lead l JOIN v309_r2_images i ON i.table_name='zsjos_lead' AND i.row_id=l.id SET l.source_type=NULLIF(i.after_image->>'$.source_type','null'),l.submission_source_type=NULLIF(i.after_image->>'$.submission_source_type','null'),l.source_user_id=NULLIF(i.after_image->>'$.source_user_id','null'),l.source_provider_user_id=NULLIF(i.after_image->>'$.source_provider_user_id','null'),l.source_provider_recorded=CAST(NULLIF(i.after_image->>'$.source_provider_recorded','null') AS UNSIGNED),l.provider_owner_type=NULLIF(i.after_image->>'$.provider_owner_type','null'),l.provider_owner_id=NULLIF(i.after_image->>'$.provider_owner_id','null'),l.provider_owner_name_snapshot=NULLIF(i.after_image->>'$.provider_owner_name_snapshot','null'),l.contribution_user_id_snapshot=NULLIF(i.after_image->>'$.contribution_user_id_snapshot','null'),l.contribution_user_name_snapshot=NULLIF(i.after_image->>'$.contribution_user_name_snapshot','null'),l.contribution_supervisor_user_id_snapshot=NULLIF(i.after_image->>'$.contribution_supervisor_user_id_snapshot','null'),l.contribution_supervisor_name_snapshot=NULLIF(i.after_image->>'$.contribution_supervisor_name_snapshot','null'),l.contribution_dept_id_snapshot=NULLIF(i.after_image->>'$.contribution_dept_id_snapshot','null'),l.contribution_dept_name_snapshot=NULLIF(i.after_image->>'$.contribution_dept_name_snapshot','null'),l.version=NULLIF(i.after_image->>'$.version','null'),l.updater=NULLIF(i.after_image->>'$.updater','null'),l.update_time=NULLIF(i.after_image->>'$.update_time','null') WHERE l.tenant_id=1 AND i.current_image<>i.after_image;
 IF EXISTS(SELECT 1 FROM zsjos_lead l JOIN v309_r2_images i ON i.table_name='zsjos_lead' AND i.row_id=l.id WHERE NOT(JSON_OBJECT('lead_no',l.lead_no,'tenant_id',l.tenant_id,'deleted',CAST(l.deleted AS UNSIGNED),'source_type',l.source_type,'submission_source_type',l.submission_source_type,'source_user_id',l.source_user_id,'source_dept_id',l.source_dept_id,'source_provider_user_id',l.source_provider_user_id,'source_provider_recorded',CAST(l.source_provider_recorded AS UNSIGNED),'provider_owner_type',l.provider_owner_type,'provider_owner_id',l.provider_owner_id,'provider_owner_name_snapshot',l.provider_owner_name_snapshot,'contribution_user_id_snapshot',l.contribution_user_id_snapshot,'contribution_user_name_snapshot',l.contribution_user_name_snapshot,'contribution_supervisor_user_id_snapshot',l.contribution_supervisor_user_id_snapshot,'contribution_supervisor_name_snapshot',l.contribution_supervisor_name_snapshot,'contribution_dept_id_snapshot',l.contribution_dept_id_snapshot,'contribution_dept_name_snapshot',l.contribution_dept_name_snapshot,'counted_at',DATE_FORMAT(l.counted_at,'%Y-%m-%d %H:%i:%s'),'owner_user_id',l.owner_user_id,'owner_identity',l.owner_identity,'version',l.version,'updater',l.updater,'update_time',DATE_FORMAT(l.update_time,'%Y-%m-%d %H:%i:%s')) <=> i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 postcondition failed'; END IF;
 UPDATE zsjos_order_approval_round r JOIN v309_r2_images i ON i.table_name='zsjos_order_approval_round' AND i.row_id=r.id SET r.order_snapshot=i.after_image->'$.order_snapshot',r.version=NULLIF(i.after_image->>'$.version','null'),r.updater=NULLIF(i.after_image->>'$.updater','null'),r.update_time=NULLIF(i.after_image->>'$.update_time','null') WHERE r.tenant_id=1 AND i.current_image<>i.after_image;
 IF EXISTS(SELECT 1 FROM zsjos_order_approval_round r JOIN v309_r2_images i ON i.table_name='zsjos_order_approval_round' AND i.row_id=r.id WHERE NOT(JSON_OBJECT('tenant_id',r.tenant_id,'deleted',CAST(r.deleted AS UNSIGNED),'order_id',r.order_id,'order_snapshot',CAST(r.order_snapshot AS JSON),'version',r.version,'updater',r.updater,'update_time',DATE_FORMAT(r.update_time,'%Y-%m-%d %H:%i:%s')) <=> i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 postcondition failed'; END IF;
 UPDATE zsjos_performance_attribution p JOIN v309_r2_images i ON i.table_name='zsjos_performance_attribution' AND i.row_id=p.id SET p.source_group=NULLIF(i.after_image->>'$.source_group','null'),p.updater=NULLIF(i.after_image->>'$.updater','null'),p.update_time=NULLIF(i.after_image->>'$.update_time','null') WHERE p.tenant_id=1 AND i.current_image<>i.after_image;
 IF EXISTS(SELECT 1 FROM zsjos_performance_attribution p JOIN v309_r2_images i ON i.table_name='zsjos_performance_attribution' AND i.row_id=p.id WHERE NOT(JSON_OBJECT('tenant_id',p.tenant_id,'deleted',CAST(p.deleted AS UNSIGNED),'lead_id',p.lead_id,'fact_type',p.fact_type,'fact_id',p.fact_id,'source_group',p.source_group,'user_id',p.user_id,'dept_id',p.dept_id,'center_id',p.center_id,'org_source',p.org_source,'updater',p.updater,'update_time',DATE_FORMAT(p.update_time,'%Y-%m-%d %H:%i:%s')) <=> i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 r2 postcondition failed'; END IF;

 provider_identity_block: BEGIN
 DECLARE pir_count INT;
 DECLARE pir_saved INT;
 DECLARE pir_now DATETIME(6) DEFAULT NOW();
 DECLARE pir_path VARCHAR(200);
 DECLARE pir_keys JSON;
 DECLARE pir_index INT DEFAULT 0;
 IF NOT EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V308') OR NOT EXISTS(SELECT 1 FROM zsjos_module_schema_version WHERE module_code='core' AND version='V308') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Provider repair requires both V308 ledgers'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('zsjos_lead','zsjos_order','zsjos_order_approval_round','zsjos_data_repair_backup') AND engine='InnoDB')<>4 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Provider repair requires transactional tables'; END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_data_repair_backup' AND column_name='old_value' AND data_type='longtext') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Provider repair requires LONGTEXT evidence'; END IF;
 DROP TEMPORARY TABLE IF EXISTS pir_plan;
 CREATE TEMPORARY TABLE pir_plan(table_name VARCHAR(64),row_id BIGINT,expected_sha CHAR(64),patch JSON,provenance JSON,
  current_image JSON,before_image JSON,after_image JSON,verified_after JSON,PRIMARY KEY(table_name,row_id)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
 SELECT COUNT(*) INTO pir_count FROM zsjos_lead WHERE tenant_id=1 AND id IN (803,843,910,1027,1056,1211,1212,1434,1616,1758,1817,1841,1951,2021,6093,6439) FOR UPDATE;
 SELECT COUNT(*) INTO pir_saved FROM zsjos_data_repair_backup WHERE repair_key='provider-identity-20261011';
 IF pir_count=0 THEN
  IF EXISTS(SELECT 1 FROM zsjos_lead WHERE tenant_id=1) OR pir_saved<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Provider repair targets missing'; END IF;
  LEAVE provider_identity_block;
