 INSERT INTO zsjos_data_repair_backup(repair_key,table_name,row_id,column_name,old_value) SELECT 'lead-source-confirmed-v309-r2',i.table_name,i.row_id,'__before__',CAST(i.before_image AS CHAR CHARACTER SET utf8mb4) FROM v309_r2_images i WHERE NOT EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='lead-source-confirmed-v309-r2' AND b.table_name=i.table_name AND b.row_id=i.row_id AND b.column_name='__before__');
